<script setup>import {computed,ref} from 'vue';import {state} from '../../domain/prototypeStore.js';const selected=ref('');const event=computed(()=>state.events.find(x=>x.id===selected.value)||state.events[0]);const detail=ref('');</script>
<template><section class="page-stack"><div class="page-heading"><div class="module-icon">图</div><div><h2>指挥态势</h2><p>统一查看事件、任务、人员、设备和物资资源</p></div></div><select v-model="selected"><option v-for="e in state.events" :key="e.id" :value="e.id">{{e.title}}</option></select><div v-if="event" class="situation-grid"><article class="panel situation-map"><button v-for="p in state.people" :key="p.id" class="point person-point" @click="detail=`${p.name} · ${p.group} · ${p.contact}`">{{p.name}}<br>{{p.contact}}</button><button v-for="m in state.materials" :key="m.id" class="point material-point" @click="detail=`${m.station}：${m.name} ${m.quantity}件，${m.status}`">{{m.station}}<br>{{m.quantity}}件</button></article><article class="panel"><h3>{{event.title}}</h3><p>{{event.location}} · {{event.status}}</p><p v-if="detail" class="action-message">{{detail}}</p><h4>关联任务</h4><p v-for="t in state.tasks.filter(t=>t.eventId===event.id)" :key="t.id">{{t.title}} · {{t.status}}</p><h4>视频设备</h4><button v-for="d in state.devices.filter(d=>d.type==='摄像头')" :key="d.id" class="secondary-button" @click="detail=`${d.name} · ${d.status}`">{{d.name}}</button></article></div><article v-if="event" class="panel"><h3>事件时间线</h3><ol class="timeline"><li v-for="x in event.timeline" :key="x.time+x.label"><strong>{{x.label}}</strong><p>{{x.detail}}</p></li></ol></article></section></template>
